#!/usr/bin/env python3
"""
Round 192o (culprits), 12 October 2026. Needs round 191o.

Climate TRACE's ownership chains; Giga's schools by name.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 192o (12 October)\n\nNeeds round 191o (guards on its heading). Tiles patch round192o_tiles.py\nbeside it. No app.js?v= bump.\n\n- Climate TRACE\'s full ownership chains (the Coalition, Lekha, 12 October:\n  storage.googleapis.com/climate_trace/ownership/ownership_all_*_071026.csv,\n  copies in tiles ct_ownership/). Tiles ct_ownership.py: each owned site\'s\n  latest full year of CO2e (100-year) from latest/sector_packages/co2e_100yr/\n  <sector>.zip (power, fossil_fuel_operations, agriculture, manufacturing,\n  mineral_extraction; one or more a run, cached monthly in\n  ct_ownership/emissions_<sector>.json), chains walked to the owners no one\n  is listed as owning. Site -> named owner has no share (counted whole);\n  owner -> owner percentages multiplied; largest share per top owner per\n  site; any missing percentage -> "unknown share, not divided"; plus every\n  site not divided. Rows ct_top_owners (capital of HQ country, spread) and\n  ct_owned_sites, under Climate > Who owns the emissions. Tested on the real\n  tables with stub emissions (9,142 owners at the top, 6,238 placed) and on a\n  synthetic package; the real packages were not reachable from the sandbox.\n- giga_school_names (route pmtiles, tiles tiles/giga_named.pmtiles, made by\n  tiles giga_api.py from Giga\'s School Location API with the GIGA_API_KEY\n  secret: /api/locations/schools-download/?country_id=..., header Api-Key,\n  per unicef/giga-maps-backend). Giga said weekly is enough and asked for\n  credit under a share-alike licence: every Giga attribution now says so.\n- Tiles fixes: open_payments keeps a year\'s pages read so far\n  (years/<year>.partial.json) and starts no page after 120 minutes (2023\n  alone took about two hours, so the 12 October run was stopped at 160);\n  animal_places_osm asks for breeding places in eight longitude bands (the\n  world query timed out at every Overpass server) and keeps the last copy\n  with a warning, trying again the next day; meat_dairy_methane tries other\n  article titles for Danish Crown and DMK and its headquarters\' country.\n- Not fixable by patch: the culprits refresh\'s tippecanoe cache keeps only\n  /usr/local/bin/tippecanoe, so split_archive.py\'s tile-join is missing\n  (abattoir_facilities, 101 MB, 12 October). The owner edits refresh.yml.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round192o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 191o" not in h.read_text(encoding="utf-8"):
        sys.exit("round192o: round 191o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round192o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round192o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round192o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
